WITH RECURSIVE x6 AS (SELECT 0 UNION ALL SELECT x5.v8893 + 1 FROM x10 WHERE x5.v8893 < 10000) SELECT x5.v8893 + 1, (DATEDIFF(@TMP, '0000-01-01') + 1) + 102, LEAD(x5.v8893, 1, 3) OVER (ORDER BY x5.v8893 * 4294967295, x5.v8893 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS x0, x5.v8893 + 800000 FROM v8892 AS x5 WHERE x5.v8893 + 4 > 5